  for(const field of ["answers","checked","paraphraseAnswers","paraphraseChecked","showKey","highlights","dictionaryCache","timers"]){ if(!state[field] || typeof state[field]!=="object" || Array.isArray(state[field]))state[field]={}; }
  for(const p of PASSAGES){const k=passageKey(p);if(!state.answers[k]||typeof state.answers[k]!=="object")state.answers[k]={};if(!state.paraphraseAnswers[k]||typeof state.paraphraseAnswers[k]!=="object")state.paraphraseAnswers[k]={};if(typeof state.paraphraseChecked[k]!=="boolean")state.paraphraseChecked[k]=false;if(!Array.isArray(state.highlights[k]))state.highlights[k]=[];state.highlights[k]=state.highlights[k].filter(h=>Number.isInteger(h.p)&&p.paragraphs[h.p]&&Number.isInteger(h.start)&&Number.isInteger(h.end)&&h.start>=0&&h.end>h.start&&h.end<=p.paragraphs[h.p].length);}
