function pauseOtherTimers(keepId){PASSAGES.forEach(p=>{if(p.id!==keepId)pauseTimer(p.id,false);});}
function pauseTimer(passageId,shouldSave=true){const k=`p${passageId}`,t=state.timers[k];if(!t)return;if(t.running&&t.lastTick){const elapsed=Math.max(0,Math.floor((Date.now()-t.lastTick)/1000));t.remaining=Math.max(0,t.remaining-elapsed);}t.running=false;t.lastTick=null;if(shouldSave)saveState();if(activePassage().id===passageId)stopTicker();}
function startTicker(){stopTicker();ticker=setInterval(()=>{const t=currentTimer();if(!t.running)return;const now=Date.now(),elapsed=Math.max(0,Math.floor((now-(t.lastTick||now))/1000));if(elapsed===0)return;t.lastTick=(t.lastTick||now)+elapsed*1000;t.remaining=Math.max(0,t.remaining-elapsed);if(t.remaining===0){t.running=false;t.lastTick=null;stopTicker();}saveState();updateTimer();},1000);}
function stopTicker(){if(ticker){clearInterval(ticker);ticker=null;}}
function updateTimer(){const t=currentTimer(),m=String(Math.floor(t.remaining/60)).padStart(2,"0"),s=String(t.remaining%60).padStart(2,"0");el.timerLabel.textContent=`Passage ${activePassage().id} timer`;el.timerDisplay.textContent=`${m}:${s}`;const action=t.running?"Pause timer":(t.remaining===0?"Time up":"Start timer");el.startPauseBtn.textContent=t.running?"Ⅱ":"▶";el.startPauseBtn.setAttribute("aria-label",action);el.startPauseBtn.title=action;el.startPauseBtn.disabled=t.remaining===0;const card=el.timerDisplay.closest(".timer-card");card.classList.toggle("timer-warning",t.remaining<=300&&t.remaining>60);card.classList.toggle("timer-danger",t.remaining<=60);}
function targetPassageId(index){return IS_EASY?pages[index].passageId:PASSAGES[index].id;}
function goToIndex(index){const max=IS_EASY?pages.length:PASSAGES.length;if(index<0||index>=max||index===state.activeIndex)return;const oldId=activePassage().id,newId=targetPassageId(index);if(oldId!==newId)pauseTimer(oldId);state.activeIndex=index;document.querySelector(".reading-pane").scrollTop=0;document.querySelector(".question-pane").scrollTop=0;closeDict();saveState();renderAll();if(currentTimer().running)startTicker();else stopTicker();}
function changeIndex(d){goToIndex(state.activeIndex+d);}
function updateNav(){const max=IS_EASY?pages.length:PASSAGES.length;el.prevPassageBtn.disabled=state.activeIndex===0;el.nextPassageBtn.disabled=state.activeIndex===max-1;el.prevPassageBtn.textContent=IS_EASY?"← Previous page":"← Previous passage";el.nextPassageBtn.textContent=IS_EASY?"Next page →":"Next passage →";}
function updateProgress(){const qs=questionsForView(),ans=state.answers[passageKey()]||{},done=qs.filter(q=>ans[q.n]).length;el.answeredCount.textContent=`${done}/${qs.length} answered`;el.scoreText.textContent=state.checked[checkKey()]?`Score: ${getScore(qs)}/${qs.length}`:"Score: --";}
function getScore(qs,key=passageKey()){const ans=state.answers[key]||{};return qs.reduce((n,q)=>n+(ans[q.n]===q.answer?1:0),0);}
function renderResult(){const p=activePassage(),qs=questionsForView();if(!state.checked[checkKey()]&&!(IS_TEACHER&&state.showKey[passageKey()])){el.resultBox.hidden=true;return;}el.resultBox.hidden=false;let msg=state.checked[checkKey()]?`Checked: <strong>${getScore(qs)}/${qs.length}</strong>.`:"";if(IS_TEACHER&&state.showKey[passageKey()])msg+=` Answer key: <strong>${qs.map(q=>globalQuestionNumber(p,q)+'.'+q.answer).join(' · ')}</strong>. Evidence is highlighted in matching question colors.`;el.resultBox.innerHTML=msg;}
function updateToolLabels(){const h=document.body.classList.contains("highlight-mode");el.highlightToggle.classList.toggle("active",h);el.highlightToggle.setAttribute("aria-label",h?"Highlight on":"Highlight off");el.highlightToggle.setAttribute("aria-pressed",String(h));el.dictionaryToggle.setAttribute("aria-pressed",String(Boolean(state.dictionaryOn)));el.highlightToggle.title=h?"Highlight: On":"Highlight: Off";el.dictionaryToggle.classList.toggle("active",Boolean(state.dictionaryOn));el.dictionaryToggle.setAttribute("aria-label",state.dictionaryOn?"Dictionary on":"Dictionary off");el.dictionaryToggle.title=state.dictionaryOn?"Dictionary: On":"Dictionary: Off";if(el.showKeyBtn){const on=Boolean(state.showKey[passageKey()]);el.showKeyBtn.textContent=on?"Hide answer key & evidence":"Show answer key & evidence";}}
function scrollToIssue(){const x=el.questionForm.querySelector(".check-feedback.wrong,.check-feedback.unanswered");if(x)x.scrollIntoView({behavior:"smooth",block:"center"});}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
function escapeAttr(v){return escapeHtml(v);}

function setFontSize(value){state.fontSize=clamp(value,16,36,18);applyFontSize();saveState();}
function applyFontSize(){const size=clamp(state.fontSize,16,36,18);document.documentElement.style.setProperty("--font-size-reading",`${size/16}rem`);document.documentElement.style.setProperty("--font-size-question",`${size/16}rem`);el.fontSizeDisplay.textContent=`${size}`;el.fontDecreaseBtn.disabled=size<=16;el.fontIncreaseBtn.disabled=size>=36;}
